import{_ as e,c as r,o as t,ai as n}from"./chunks/framework.BrjRfu4a.js";const b=JSON.parse('{"title":"국채시장 동향 | 2024년 국고채 시장 | 한국 국채","description":"2024년 우리나라 국고채 시장은 대내외 불확실성 확대에도 불구하고 글로벌 국채시장 대비 상대적으로 안정적인 모습을 보였습니다. 국고채 발행량은 2023년 발행량(165.7조원) 대비 8.0조원 줄어든 총 157.7조원으로, 코로나19 발발로 인해 발행량이 급증했던 2020~2021년 이후 감소세가 이어졌습니다.","frontmatter":{"title":"국채시장 동향 | 2024년 국고채 시장 | 한국 국채","description":"2024년 우리나라 국고채 시장은 대내외 불확실성 확대에도 불구하고 글로벌 국채시장 대비 상대적으로 안정적인 모습을 보였습니다. 국고채 발행량은 2023년 발행량(165.7조원) 대비 8.0조원 줄어든 총 157.7조원으로, 코로나19 발발로 인해 발행량이 급증했던 2020~2021년 이후 감소세가 이어졌습니다.","head":[["meta",{"property":"og:title","content":"국채시장 동향 | 2024년 국고채 시장 | 한국 국채"}],["meta",{"property":"og:description","content":"2024년 우리나라 국고채 시장은 대내외 불확실성 확대에도 불구하고 글로벌 국채시장 대비 상대적으로 안정적인 모습을 보였습니다. 국고채 발행량은 2023년 발행량(165.7조원) 대비 8.0조원 줄어든 총 157.7조원으로, 코로나19 발발로 인해 발행량이 급증했던 2020~2021년 이후 감소세가 이어졌습니다."}],["meta",{"property":"og:image","content":"/images/RiskQuantHaun.png"}],["meta",{"property":"og:url","content":"https://risk-quant-haun.github.io/ko/korean-treasury-bonds/2024-market/treasury-bond-trends"}],["link",{"rel":"alternate","hreflang":"ko","href":"https://risk-quant-haun.github.io/ko/korean-treasury-bonds/2024-market/treasury-bond-trends"}],["link",{"rel":"alternate","hreflang":"en","href":"https://risk-quant-haun.github.io/korean-treasury-bonds/2024-market/treasury-bond-trends"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://risk-quant-haun.github.io/ko/korean-treasury-bonds/2024-market/treasury-bond-trends"}],["link",{"rel":"canonical","href":"https://risk-quant-haun.github.io/ko/korean-treasury-bonds/2024-market/treasury-bond-trends"}]],"date":"2025-03-07T00:00:00.000Z"},"headers":[],"relativePath":"ko/korean-treasury-bonds/2024-market/treasury-bond-trends.md","filePath":"ko/korean-treasury-bonds/2024-market/treasury-bond-trends.md"}'),o={name:"ko/korean-treasury-bonds/2024-market/treasury-bond-trends.md"};function s(i,a,d,p,h,l){return t(),r("div",null,a[0]||(a[0]=[n('<h1 id="🏦-국채시장-동향" tabindex="-1">🏦 국채시장 동향 <a class="header-anchor" href="#🏦-국채시장-동향" aria-label="Permalink to &quot;🏦 국채시장 동향&quot;">​</a></h1><p><strong>2024년 국고채 시장 | 한국 국채 | 2025.03.07</strong></p><h2 id="_1️⃣-개요" tabindex="-1">1️⃣ 개요 <a class="header-anchor" href="#_1️⃣-개요" aria-label="Permalink to &quot;1️⃣ 개요&quot;">​</a></h2><p>2024년 우리나라 국고채 시장은 대내외 불확실성 확대에도 불구하고 글로벌 국채시장 대비 상대적으로 안정적인 모습을 보였습니다. 국고채 발행량은 2023년 발행량(165.7조원) 대비 8.0조원 줄어든 총 157.7조원으로, 코로나19 발발로 인해 발행량이 급증했던 2020~2021년 이후 감소세가 이어졌습니다.</p><h2 id="_2️⃣-연간-동향" tabindex="-1">2️⃣ 연간 동향 <a class="header-anchor" href="#_2️⃣-연간-동향" aria-label="Permalink to &quot;2️⃣ 연간 동향&quot;">​</a></h2><p>2024년 국내외 경제상황을 고려한 전략적 국고채 발행으로 안정적 국채금리 유지를 통해 국가 재정정책을 뒷받침하며 긴요한 역할을 수행하였습니다. 국가채무 잔액을 실제로 증가시키는 순발행 규모(49.2조원)는 전년 대비 12.3조원 감소한 반면, 만기도래에 따른 차환발행 규모(108.5조원)는 전년보다 4.3조원 증가하였습니다.</p><p>외국인의 국고채 투자는 국채통합계좌 개통, 세계국채지수(WGBI) 편입 등 정부의 투자환경 개선 노력으로 순유입(+19.2조원)을 이어갔으며, 외국인의 보유잔액은 238.7조원, 보유비중은 22.8%로 역대 최고치를 기록하였습니다.</p><h2 id="_3️⃣-2024년-국채시장-흐름" tabindex="-1">3️⃣ 2024년 국채시장 흐름 <a class="header-anchor" href="#_3️⃣-2024년-국채시장-흐름" aria-label="Permalink to &quot;3️⃣ 2024년 국채시장 흐름&quot;">​</a></h2><p>2024년 초 국내외 경제지표에 따라 안정적으로 등락하던 국고채 금리는 4월부터 이스라엘-이란 간 지정학적 긴장 고조로 인한 국제유가 상승과 연준의 금리인하 신중론 부각으로 상승 흐름이 나타났으며, 이에 따라 국고채 금리는 연중 최고치를 기록했습니다(10년물 기준 3.707%).</p><p>그러나 6월 ECB가 약 2년만에 통화정책 방향을 전환하여 기준금리를 △0.25%P 인하하고 미국의 경기지표 둔화로 연준의 조기 금리인하 가능성이 대두되면서 글로벌 금리와 동조화되어 하락하는 흐름을 보였습니다.</p><p>8월에는 내년도 국채발행량이 시장의 예상치를 웃돌면서 금리가 일시적으로 상승하였으나, 10월 우리나라 국채시장의 세계국채지수(WGBI) 편입, 연준의 10월 기준금리 빅 컷(△0.5%P)으로 금리가 재차 하락하였습니다.</p><p>11월 미국 대선 이후 트럼프 2기 행정부의 관세 정책에 대한 우려로 수출의존도가 높은 우리나라의 성장률 전망에 대한 우려가 커졌고, 이에 따라 한국은행이 10월, 11월 2회 연속 금리인하를 실시하면서 금리 하락 폭이 확대되었습니다. 이에 따라 국고채 금리는 연중 최저치까지 하락하면서 2022년 3월 이후 가장 낮은 수준을 기록하였습니다(10년물 기준 2.579%).</p><p>12월에는 국내 정치적 불확실성이 확대되는 가운데 트럼프 2기 행정부의 관세정책 등에 따른 인플레이션 재점화 우려 및 12월 FOMC에서 연준의 2025년 기준금리 인하 예상 폭이 △100bp → 50bp로 축소되면서 국고채 금리는 다소 상승하는 흐름을 보였습니다.</p><p>이에 따라 2024년말 국고채 3년물 금리는 2.596%로 2023년말 대비 △55.8bp 하락, 10년물 금리는 2.855%로 2023년말 대비 △32.8bp 하락 마감하였습니다.</p><h2 id="_4️⃣-월별-국채시장-동향" tabindex="-1">4️⃣ 월별 국채시장 동향 <a class="header-anchor" href="#_4️⃣-월별-국채시장-동향" aria-label="Permalink to &quot;4️⃣ 월별 국채시장 동향&quot;">​</a></h2><h3 id="상반기-1월-6월" tabindex="-1">상반기 (1월-6월) <a class="header-anchor" href="#상반기-1월-6월" aria-label="Permalink to &quot;상반기 (1월-6월)&quot;">​</a></h3><p>1월부터 3월까지는 주로 국내외 경제지표와 통화정책 방향성에 대한 불확실성으로 금리가 등락을 거듭했습니다. 4월에는 중동 지정학적 긴장 고조와 미국 소비자물가지수 상승으로 금리가 크게 상승했으며, 5월에는 미국 경기지표 둔화와 지정학적 긴장 완화로 소폭 하락했습니다.</p><p>6월에는 ECB의 기준금리 인하 및 미국 경기 둔화 징후로 인한 금리인하 기대감이 커지면서 국고채 금리가 큰 폭으로 하락했습니다. 6월말 금리는 3년물 △27.0bp, 10년물 △31.2bp, 30년물 △23.2bp 전월대비 하락하였습니다.</p><h3 id="하반기-7월-12월" tabindex="-1">하반기 (7월-12월) <a class="header-anchor" href="#하반기-7월-12월" aria-label="Permalink to &quot;하반기 (7월-12월)&quot;">​</a></h3><p>7월에는 디스인플레이션 추세가 이어질 것이라는 기대감으로, 8월에는 중동 지역 지정학적 긴장 완화와 연준의장의 금리 인하 시사 발언으로 금리가 하락했습니다. 9월에는 우리나라 소비자물가지수가 2.0%로 3년 5개월만에 최저치를 기록하고 연준의 빅 컷 단행으로 금리가 추가 하락했습니다.</p><p>10월에는 한국은행의 기준금리 인하에도 불구하고 중동지역 긴장 재고조와 미국 대선 관련 불확실성으로 금리가 상승했습니다. 11월에는 경기 둔화 우려와 한국은행의 추가 금리인하로 금리가 큰 폭으로 하락했습니다.</p><p>12월에는 연말 국고채 발행량 감소에도 불구하고 트럼프 신정부의 관세 정책에 따른 인플레이션 우려와 국내 정치적 불확실성 확대로 중장기물 금리가 상승했습니다. 반면, 내년 경기전망에 대한 우려로 단기물 금리는 소폭 하락했습니다.</p><h2 id="_5️⃣-결론" tabindex="-1">5️⃣ 결론 <a class="header-anchor" href="#_5️⃣-결론" aria-label="Permalink to &quot;5️⃣ 결론&quot;">​</a></h2><p>2024년 국고채 시장은 대내외 불확실성 확대에도 불구하고 외국인 투자자들의 꾸준한 국고채 투자와 정부의 전략적 국고채 발행 및 국채시장 선진화 정책 등에 힘입어 상대적으로 안정적인 모습을 보였습니다. 특히 세계국채지수(WGBI) 편입이라는 중요한 성과를 이루면서 글로벌 투자자들에게 인정받는 선진 시장으로 자리매김하였습니다.</p>',24)]))}const k=e(o,[["render",s]]);export{b as __pageData,k as default};
